function districtId(x,y){return Math.max(0,Math.min(1,Math.floor(y/(MAP/2))))*3+Math.max(0,Math.min(2,Math.floor(x/(MAP/3))))}
function worldRegionId(x,y){if(y<MAP*.25)return 0;if(y>=MAP*.75)return 1;if(x>=MAP*.75)return 2;if(x<MAP*.25)return 3;return -1}
function worldTheme(x,y){const id=worldRegionId(x,y);return id<0?districts[districtId(x,y)]:worldRegions[id]}
function mapAreaId(x,y){const col=Math.max(0,Math.min(4,Math.floor(x/(MAP/5)))),row=Math.max(0,Math.min(7,Math.floor(y/(MAP/8))));return row*5+col}
function updateDistrict(){const id=districtId(state.player.x,state.player.y),mapId=mapAreaId(state.player.x,state.player.y),region=worldRegionId(state.player.x,state.player.y);if(state.district!==id){if(state.district>=0&&region<0&&state.regionId<0)showToast('ENTERING · '+districts[id].name);state.district=id}if(state.regionId!==region){if(state.regionId!==-2)showToast(region>=0?'ENTERING · '+worldRegions[region].name:'BACK TO CENTRAL BAYBELL');state.regionId=region}if(state.mapAreaId!==mapId){if(state.mapAreaId>=0)showToast('MAP '+String(mapId+1).padStart(2,'0')+' · '+mapAreas[mapId].name.toUpperCase());state.mapAreaId=mapId}}

