function walkable(x,y){const tx=Math.floor(x/T),ty=Math.floor(y/T),mx=((tx%6)+6)%6,my=((ty%6)+6)%6;return mx<=2||mx>=5||my<=2||my>=5}
function road(x,y){const tx=Math.floor(x/T),ty=Math.floor(y/T);return roadX(tx)||roadY(ty)}
function posFor(i){return{x:16+((i*3+2)%10)*STEP,y:48+((i*5+2)%10)*STEP}}
