 if(px>MAP-40||py>MAP-40)continue;const axis=horiz?'x':'y',lane=horiz?py:px,speed=28+((x*5+y*3)%8);state.cars.push({x:px,y:py,angle:horiz?(direction>0?0:Math.PI):(direction>0?Math.PI/2:-Math.PI/2),color:colors[(x*7+y*3)%colors.length],police:false,rival:false,health:3,occupied:false,traffic:true,axis,lane,direction,speed,baseSpeed:speed,currentSpeed:speed,hitCooldown:0});
