 state.missionActive=true;state.progress=0;state.escapeTimer=0;const m=missions[idx],p=posFor(idx);missionCount.textContent='JOB '+String(idx+1).padStart(2,'0')+' / 25';contactEl.textContent=m[1].toUpperCase();missionTitle.textContent=m[0];missionLine.textContent=m[2];chapterEl.textContent=['ACT I · THE BLUE SEAL','ACT II · LOOSE THREADS','ACT III · THE HEAT','ACT IV · QUIET TIDE','ACT V · BAYBELL FOREVER'][Math.min(4,Math.floor(idx/5))];
 state.pickups=[];state.wreck=null;state.sideJob=null;
 if(m[3]==='collect'){let n=idx<5?3:idx<15?4:5;for(let i=0;i<n;i++){state.pickups.push({x:p.x+(i%3-1)*22+((idx*13+i*7)%17),y:p.y+(Math.floor(i/3)-.5)*28+((idx*5+i*11)%15),kind:'cash',got:false})}missionLine.textContent='Collect '+n+' envelopes. Be quick about it.'}
 if(m[3]==='wreck'){const health=3+Math.min(2,Math.floor(idx/8)),car={x:p.x,y:p.y,angle:0,color:'#cc4e62',police:false,rival:true,health,occupied:false};state.cars.push(car);state.wreck=car;missionLine.textContent='Rival ride: '+health+' hits to total it.'}
