function placeStarterCar(){let c=state.cars.find(a=>Math.hypot(a.x-112,a.y-48)<40);if(!c){c={x:112,y:48,angle:0,color:'#e9a958',police:false,rival:false,health:3,occupied:false,traffic:false};state.cars.push(c)}c.x=112;c.y=48;c.angle=0;c.traffic=false;c.axis='x';c.lane=48;c.currentSpeed=0}
const introSections=[
 {chapter:'A CITY AFTER DARK',title:'Baybell never sleeps.',caption:'Neon paints the harbor streets pink and blue. Somewhere in the night, a newcomer is looking for a way in.',text:'Baybell never really sleeps. It just changes shifts. At dawn, gulls patrol the fish market; after dark, neon paints the puddles pink and blue. Freight horns roll in from the harbor, and every block has a different story about who owns the night. You came here with a patched coat, an empty wallet, and a name nobody remembers. Auntie Mags gives you a booth and a first parcel stamped with a blue brass seal: QUIET TIDE. Hidden in its wrapping is a torn harbor manifest listing entire streets as cargo. The harbor runs on cargo, rumors, and favors; the rest of the city follows its own clock. Everyone is in a hurry, even the people standing still.'},
 {chapter:'A PIGEON WITH A PLAN',title:'Meet Rook.',caption:'Auntie Mags offers a booth, a hot meal, and a first job: borrow a car, then deliver a parcel that belongs to somebody.',text:'Your name is Rook. The locals say it suits you: sharp-eyed, hard to scare, and always looking for the next opening. Auntie Mags runs a diner with a back booth for people who need a second chance, or at least a first paycheck. She points you toward a car nobody will miss, then a parcel that definitely belongs to somebody. The parcel’s manifest points to a redevelopment deal called Quiet Tide. Mags asks you to keep moving and keep the page quiet; the streets quickly make that impossible.'},
 {chapter:'FAVORS HAVE A PRICE',title:'Everybody knows somebody.',caption:'Pip counts the city’s loose change. Trixie knows its secrets. Rico wants respect. Madam Marlowe wants results.',text:'Pip Sprocket knows every loose dollar between the boardwalk and the rail yards, and can turn a handful of envelopes into rent money. Trixie Quill trades in rumors, addresses, and carefully worded warnings. Rico Rumble thinks every disagreement should end with a dented bumper. And Madam Marlowe, who owns the quietest table in the loudest restaurant, is building something bigger than any of them. Pip finds payments stamped with the same seal. Trixie recognizes the names on the deed. Rico admits his crew has been paid to scare the harbor families away. Every favor adds another page to the same ledger.'},
 {chapter:'THE HEAT RISES',title:'The city pushes back.',caption:'Officer Latch keeps a careful eye on the streets. Make enough noise and the patrols multiply; disappear long enough and the sirens drift away.',text:'Officer Latch follows your trail, then finally tells you why: he is investigating Quiet Tide, not protecting it. Madam Marlowe is using shell companies and staged gang trouble to buy the waterfront cheap. Latch has no proof that will survive court. Your scattered deliveries can find it. Keep moving, break line of sight, and let the city swallow the sirens.'},
 {chapter:'ONE LAST RUN',title:'Make it count.',caption:'Small errands grow into gang feuds, citywide chases, and a score big enough to change Rook’s life—for better or worse.',text:'The four corners of Baybell reveal what Quiet Tide really means: Marlowe plans to clear the old harbor and sell it to an offshore resort company. The final score is not money—it is the original ledger, enough to prove the fraud and save the neighborhoods. Mags, Pip, Trixie, Rico, and even Latch each hold one piece of the way in. Get the pages to the public before Marlowe’s last convoy leaves the docks. The night is waiting, Rook. Best find a set of wheels.'}
];
