function drawIntroPerson(x,y,coat,kind=0){ctx.fillStyle='#12141c';ctx.fillRect(x-4,y+5,9,3);ctx.fillStyle=coat;ctx.fillRect(x-4,y-3,8,9);ctx.fillStyle='#d6b692';ctx.fillRect(x-3,y-8,6,5);ctx.fillStyle=kind===1?'#dfb451':'#282630';ctx.fillRect(x-4,y-9,8,2);ctx.fillStyle='#fff0cf';ctx.fillRect(x+1,y-6,1,1)}
function drawIntroScene(now){const t=(now-state.introStartTime)/1000,scene=state.introCue;const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#17192b');sky.addColorStop(.55,'#51314a');sky.addColorStop(1,'#171a25');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // Distant skyline drifts gently behind the foreground.
 for(let i=0;i<13;i++){let x=((i*27-Math.floor(t*4)%27)+256)%290-17,h=24+(i*19%47),w=17+(i*11%15),y=112-h;ctx.fillStyle=i%3===0?'#222435':'#292735';ctx.fillRect(x,y,w,h);ctx.fillStyle='#e5a959';for(let wy=y+7;wy<108;wy+=9)for(let wx=x+4;wx<x+w-3;wx+=7)if(((Math.floor(wx)+Math.floor(wy)+i)%4)!==0){ctx.globalAlpha=.55+.35*Math.sin(t*2+i+wx);ctx.fillRect(wx,wy,2,3)}ctx.globalAlpha=1}
 ctx.fillStyle='#34414a';ctx.fillRect(0,112,W,27);ctx.fillStyle='#61717b';for(let i=0;i<12;i++){let x=(i*26+Math.floor(t*13))%280-18;ctx.fillRect(x,118+(i%3)*6,13,1)}
 // The diner, docks and warehouse change with each chapter.
 if(scene===0){ctx.fillStyle='#202433';ctx.fillRect(153,73,85,39);ctx.fillStyle='#596573';ctx.fillRect(162,65,6,48);ctx.fillRect(215,57,5,56);ctx.fillRect(159,68,64,3);ctx.fillStyle='#e26382';ctx.fillRect(187,84,24,7);ctx.fillStyle='#ffde91';ctx.fillRect(191,86,16,2);ctx.fillStyle='#12151d';ctx.fillRect(0,121,256,15);ctx.fillStyle='#d04f63';ctx.fillRect(196,121,18,5);ctx.fillRect(205,116,2,12)}
 if(scene===1){ctx.fillStyle='#29252e';ctx.fillRect(147,67,102,67);ctx.fillStyle='#e7bc78';ctx.fillRect(154,73,87,8);ctx.fillStyle='#c74265';ctx.fillRect(163,75,68,4);ctx.fillStyle='#f9d17c';ctx.font='bold 7px monospace';ctx.textAlign='center';ctx.fillText("MAG'S",197,79);ctx.fillStyle='#6cbdb7';ctx.fillRect(157,91,24,25);ctx.fillRect(187,91,24,25);ctx.fillStyle='#161923';ctx.fillRect(159,93,20,21);ctx.fillRect(189,93,20,21);ctx.fillStyle='#d66c77';ctx.fillRect(218,100,14,34);ctx.fillStyle='#816547';ctx.fillRect(221,105,8,2)}
 if(scene===2){ctx.fillStyle='#272733';ctx.fillRect(160,75,95,50);ctx.fillStyle='#dc6680';ctx.fillRect(167,82,62,3);ctx.fillStyle='#f2c56e';ctx.fillRect(232,82,9,3);drawIntroPerson(174,118,'#d6a35a',1);drawIntroPerson(198,118,'#6ba7a2',0);drawIntroPerson(224,118,'#b46678',0);ctx.fillStyle='#ffcf70';for(let i=0;i<4;i++){let y=98+((t*18+i*13)%26);ctx.fillRect(185+(i%2)*13,y,3,3)}}
 if(scene===3){ctx.fillStyle='#222535';ctx.fillRect(155,76,105,58);ctx.fillStyle='#576273';for(let i=0;i<5;i++)ctx.fillRect(164+i*17,84,8,10);ctx.fillStyle='#ec637e';ctx.fillRect(164,100,67,3)}
 if(scene===4){ctx.fillStyle='#252631';ctx.fillRect(150,62,110,73);ctx.fillStyle='#414453';ctx.fillRect(159,70,94,63);ctx.fillStyle='#e4be71';ctx.fillRect(165,76,82,2);for(let i=0;i<4;i++){ctx.fillStyle='#596171';ctx.fillRect(165+i*21,85,15,21);ctx.fillStyle='#ffcf78';ctx.fillRect(168+i*21,88,3,3);ctx.fillRect(175+i*21,88,3,3)}ctx.fillStyle='#d86579';ctx.fillRect(183,114,33,19);ctx.fillStyle='#151720';ctx.fillRect(188,117,23,16)}
 // Sidewalk and broad two-way avenue with painted lines.
 ctx.fillStyle='#777363';ctx.fillRect(0,137,W,12);ctx.fillStyle='#c6bd9e';ctx.fillRect(0,137,W,1);ctx.fillStyle='#444650';ctx.fillRect(0,149,W,75);ctx.fillStyle='#e9c94d';for(let x=-32+(Math.floor(t*22)%36);x<W;x+=36)ctx.fillRect(x,184,18,2);ctx.fillStyle='#d9d5c7';ctx.fillRect(0,149,W,1);ctx.fillRect(0,222,W,1);
 // Moving traffic, a chapter-specific action beat, and rain during the chase.
 const carX=((t*38+286)%330)-34;drawIntroCar(carX,164,'#d56773');drawIntroCar(256-carX,207,'#719ca7',Math.PI);
 if(scene===0){drawIntroRook(112+Math.sin(t*1.5)*15,130,Math.floor(t*6)%2)}
 if(scene===1){drawIntroRook(150+Math.min(1,t/3)*12,130,Math.floor(t*7)%2);ctx.fillStyle='#62e4d4';ctx.fillRect(149,126,3,4)}
 if(scene===2){drawIntroRook(147,130,Math.floor(t*5)%2);ctx.fillStyle='#ffc86f';ctx.fillRect(152,121,7,5);ctx.fillStyle='#fff0b1';ctx.fillRect(154,122,2,2)}
 if(scene===3){drawIntroCar(105+Math.sin(t*2)*8,164,'#bb576c');drawIntroCar(68+((t*52)%135),207,'#e7e2d1',0,true);ctx.fillStyle='rgba(191,216,236,.55)';for(let i=0;i<24;i++){let x=(i*37+Math.floor(t*78))%260,y=(i*23+Math.floor(t*105))%224;ctx.fillRect(x,y,1,5)}}
 if(scene===4){drawIntroRook(160,130,Math.floor(t*8)%2);drawIntroCar(20+((t*65)%240),164,'#dfaa58')}
 // Soft vignette keeps the story lettering readable.
 const vignette=ctx.createRadialGradient(130,110,48,130,110,180);vignette.addColorStop(0,'rgba(8,10,18,0)');vignette.addColorStop(1,'rgba(8,10,18,.28)');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);
}
function introAnimationLoop(now){if(!state.introPlaying)return;drawIntroScene(now);state.introRaf=requestAnimationFrame(introAnimationLoop)}
function stopIntroTimer(){if(state.introCueTimer){clearInterval(state.introCueTimer);state.introCueTimer=null}}
function finishIntro(){if(!state.introPlaying)return;state.introPlaying=false;stopIntroTimer();if(state.introAudio){state.introAudio.onended=null;state.introAudio.pause();state.introAudio=null}if(window.speechSynthesis)window.speechSynthesis.cancel();introScreen.classList.remove('visible');audio.pause();audio.volume=.2;startGame()}
function beginIntro(){if(state.started||state.introPlaying)return;state.introPlaying=true;titleScreen.classList.add('hidden');introScreen.classList.add('visible');introStatusEl.textContent='PREPARING NARRATION…';setIntroCue(0);state.introStartTime=performance.now();requestAnimationFrame(introAnimationLoop);
 state.introCueTimer=setInterval(()=>{const estimated=introTotalWords/135*60*1000;setIntroCue((performance.now()-state.introStartTime)/estimated)},250);
 (async()=>{try{if(!window.websim?.textToSpeech)throw new Error('Narration unavailable');const result=await window.websim.textToSpeech({text:introScript,generateFile:true});if(!state.introPlaying)return;if(!result?.url)throw new Error('No audio returned');stopIntroTimer();state.introAudio=new Audio(result.url);state.introAudio.preload='auto';state.introAudio.onloadedmetadata=()=>{introStatusEl.textContent='BAYBELL · '+Math.ceil(state.introAudio.duration/60)+' MIN';};state.introAudio.ontimeupdate=()=>{if(state.introAudio?.duration)setIntroCue(state.introAudio.currentTime/state.introAudio.duration)};state.introAudio.onended=finishIntro;state.introAudio.onerror=()=>{if(state.introPlaying)finishIntro()};await state.introAudio.play();}catch(error){if(!state.introPlaying)return;introStatusEl.textContent='NARRATING THE CITY…';const predicted=introTotalWords/135*60*1000;state.introStartTime=performance.now();state.introCueTimer=setInterval(()=>setIntroCue((performance.now()-state.introStartTime)/predicted),250);try{await window.websim.textToSpeech({text:introScript})}catch(e){console.warn('Narration playback unavailable',e)}if(state.introPlaying)finishIntro()}})();
}
function startTaxiMode(){if(state.started)return;state.mode='taxi';state.started=true;state.paused=false;state.complete=false;document.querySelector('.game-frame').classList.add('playing','taxi-mode');titleScreen.classList.add('hidden');if(soundOn)audio.play().catch(()=>{});makeCars();makePedestrians();state.police=[];state.roadblock=null;state.pickups=[];state.wreck=null;state.sideJob=null;state.safehouse=null;state.safehouseTimer=0;state.wanted=0;state.missionActive=false;state.player={x:48,y:48,dir:0,speed:0,inCar:true,car:null,bonk:0};state.camera.x=0;state.camera.y=0;state.skids=[];state.effects=[];try{const data=JSON.parse(localStorage.getItem('neonborough-taxi-save')||'{}');state.money=Number(data.money)||0;state.taxiCompleted=Number(data.completed)||0;state.taxiStats={...state.taxiStats,...(data.stats||{}),rides:Number(data.stats?.rides)||Number(data.completed)||0}}catch{state.money=0;state.taxiCompleted=0;state.taxiStats={rides:0,streak:0,rating:5,tips:0,bestFare:0}}const cab={x:48,y:48,angle:0,color:'#e7b84f',police:false,rival:false,taxi:true,health:3,occupied:true,traffic:false,axis:'x',lane:48,direction:1,speed:0,baseSpeed:0,currentSpeed:0,hitCooldown:0};state.cars.push(cab);state.player.car=cab;createTaxiRide(true);updateUI();requestAnimationFrame(loop)}
function startGame(){if(state.started)return;state.started=true;cityBoardButton.disabled=false;state.mode='story';state.taxiRide=null;state.friendCall=null;state.friendMission=null;state.friendCallTimer=24+Math.random()*18;state.paused=false;document.querySelector('.game-frame').classList.remove('taxi-mode');document.querySelector('.game-frame').classList.add('playing');titleScreen.classList.add('hidden');if(soundOn)audio.play().catch(()=>{});if(!state.cars.length)makeCars();let saved=localStorage.getItem('neonborough-save');if(saved){try{const s=JSON.parse(saved);state.money=s.money||0;state.mission=Math.min(s.mission||0,25);state.friendCompleted=Number(s.friendCompleted)||0;state.friendMissed=Number(s.friendMissed)||0;state.friendDeck=Array.isArray(s.friendDeck)?s.friendDeck.filter(n=>Number.isInteger(n)&&n>=0&&n<friendContacts.length):[];state.activityDone=Array.isArray(s.activityDone)?s.activityDone.filter(n=>Number.isInteger(n)&&n>=0&&n<cityActivities.length):[];state.player.x=s.x??48;state.player.y=s.y??48;state.player.inCar=!!s.inCar;if(state.player.inCar){state.player.car={x:state.player.x,y:state.player.y,angle:0,color:'#e9a958',occupied:true,health:s.carHealth??3,axis:'x',lane:state.player.y,currentSpeed:0};state.cars.push(state.player.car)}}catch{}}
 if(!state.cars.length)makeCars();if(state.mission===0)placeStarterCar();initMission();requestAnimationFrame(loop)}
function save(){if(state.mode==='taxi'){localStorage.setItem('neonborough-taxi-save',JSON.stringify({money:state.money,completed:state.taxiCompleted,stats:state.taxiStats}));}else{localStorage.setItem('neonborough-save',JSON.stringify({money:state.money,mission:state.mission,x:state.player.x,y:state.player.y,inCar:state.player.inCar,carHealth:state.player.car?.health??3,friendCompleted:state.friendCompleted,friendMissed:state.friendMissed,friendDeck:state.friendDeck,activityDone:state.activityDone}))}updateTitleOptions()}
function updateTitleOptions(){const hasSave=!!localStorage.getItem('neonborough-save'),hasTaxi=!!localStorage.getItem('neonborough-taxi-save');startBtn.innerHTML=hasSave?'CONTINUE GAME <span>▶</span>':'GAME MODE <span>▶</span>';taxiStartBtn.innerHTML=hasTaxi?'CONTINUE TAXI <span>▶</span>':'TAXI MODE <span>▶</span>';newRunButton.hidden=!hasSave}
function randomTaxiPoint(){const lane=nearestRoadLane(Math.random()*(MAP-1)),horizontal=Math.random()<.5;if(horizontal)return{x:64+Math.floor(Math.random()*9)*STEP,y:lane};return{x:lane,y:64+Math.floor(Math.random()*9)*STEP}}
function nextTaxiContract(){if(!state.taxiContractDeck?.length){state.taxiContractDeck=Array.from({length:taxiContracts.length},(_,i)=>i);for(let i=state.taxiContractDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.taxiContractDeck[i],state.taxiContractDeck[j]]=[state.taxiContractDeck[j],state.taxiContractDeck[i]]}}return taxiContracts[state.taxiContractDeck.pop()]}
function createTaxiRide(first=false){let pickup=first?{x:240,y:48}:randomTaxiPoint(),destination=first?{x:nearestRoadLane(1460),y:1040}:randomTaxiPoint(),tries=0;while(Math.abs(destination.x-pickup.x)+Math.abs(destination.y-pickup.y)<420&&tries++<20)destination=randomTaxiPoint();const names=['Mina','Lou','Rae','Dex','June','Sol','Benny','Iris'];state.taxiRide={pickup,destination,onboard:false,distance:0,lastX:state.player.x,lastY:state.player.y,name:names[(state.taxiCompleted*3+Math.floor(Math.random()*names.length))%names.length],contract:nextTaxiContract(),elapsed:0,patienceMax:105,patienceLeft:105,patienceWarned:false,clean:true,pedHits:0,visitedAreas:[],directDistance:Math.abs(destination.x-pickup.x)+Math.abs(destination.y-pickup.y)};updateTaxiUI()}
function nextTaxiScript(){if(!state.taxiScriptDeck?.length){state.taxiScriptDeck=Array.from({length:taxiScripts.length},(_,i)=>i);for(let i=state.taxiScriptDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.taxiScriptDeck[i],state.taxiScriptDeck[j]]=[state.taxiScriptDeck[j],state.taxiScriptDeck[i]]}if(state.taxiScriptDeck.length>1&&state.taxiScriptDeck[state.taxiScriptDeck.length-1]===state.taxiDialogueIndex)[state.taxiScriptDeck[0],state.taxiScriptDeck[state.taxiScriptDeck.length-1]]=[state.taxiScriptDeck[state.taxiScriptDeck.length-1],state.taxiScriptDeck[0]]}state.taxiDialogueIndex=state.taxiScriptDeck.pop();return taxiScripts[state.taxiDialogueIndex]}
function showTaxiSpeech(name,line){taxiSpeechEl.querySelector('.speech-name').textContent=name.toUpperCase()+' SAYS';taxiSpeechLineEl.textContent='“'+line+'”';taxiSpeechEl.classList.add('visible');state.taxiSpeechTimer=8}
function taxiFare(){return 10+Math.floor((state.taxiRide?.distance||0)/64)*2}
function taxiEstimate(){const r=state.taxiRide;if(!r)return 10;return 10+Math.floor((Math.abs(r.destination.x-r.pickup.x)+Math.abs(r.destination.y-r.pickup.y))/64)*2}
function updateTaxiUI(){if(state.mode!=='taxi')return;const r=state.taxiRide;chapterEl.textContent='TAXI SHIFT';missionCount.textContent='FARES '+String(state.taxiStats.rides).padStart(2,'0')+' · ★ '+state.taxiStats.rating.toFixed(1);contactEl.textContent=r?.onboard?r.contract.name.toUpperCase():'NEW FARE REQUEST';missionTitle.textContent=r?(r.onboard?'DROP OFF '+r.name.toUpperCase():'PICK UP '+r.name.toUpperCase()):'Waiting for a fare';missionLine.textContent=r?(state.taxiSpeechTimer>0&&state.taxiDialogue?'“'+state.taxiDialogue+'”':r.onboard?'E TO DROP OFF · '+r.contract.objective:r.contract.name+' · E TO PICK UP'): 'Find a passenger to start your shift.';const shownFare=r?.onboard?taxiFare():10;if(state.lastMeterFare!==shownFare){state.lastMeterFare=shownFare;meterFareEl.classList.remove('tick');void meterFareEl.offsetWidth;meterFareEl.classList.add('tick');setTimeout(()=>meterFareEl.classList.remove('tick'),180)}meterFareEl.textContent='$'+shownFare;meterDistanceEl.textContent=r?.onboard?Math.floor(r.distance)+' M · '+Math.ceil(r.patienceLeft)+'S LEFT':r?'REQ · '+r.contract.objective.toUpperCase():'READY FOR FARE';meterFillEl.style.width=(r?.onboard?Math.min(100,r.distance/1600*100):0)+'%'}
function taxiContractMet(r,baseFare){const c=r.contract;switch(c.type){case'rush':return r.elapsed<=c.threshold;case'smooth':return r.clean;case'explore':return new Set(r.visitedAreas).size>=c.threshold;case'direct':return r.distance<=r.directDistance*c.threshold;case'longhaul':return r.distance>=c.threshold;case'pedestrian':return r.pedHits===0;case'heat':return state.wanted===0;case'streak':return state.taxiStats.streak+1>=c.threshold;case'fare':return baseFare>=c.threshold;case'patience':return c.threshold===1?r.patienceLeft>0:r.patienceLeft>=c.threshold;default:return false}}
function taxiInteract(){const r=state.taxiRide,p=state.player;if(!r)return;if(!r.onboard){if(Math.hypot(p.x-r.pickup.x,p.y-r.pickup.y)>42){showToast('PULL UP BESIDE '+r.name.toUpperCase());return}r.onboard=true;r.distance=0;r.elapsed=0;r.patienceLeft=r.patienceMax;r.patienceWarned=false;r.clean=true;r.pedHits=0;r.visitedAreas=[mapAreaId(p.x,p.y)];r.lastX=p.x;r.lastY=p.y;state.taxiDialogue=nextTaxiScript();showTaxiSpeech(r.name,state.taxiDialogue);spawnBurst(r.pickup.x,r.pickup.y,'#62e4d4',7);play(pickupSound);showToast(r.name.toUpperCase()+' BOARDED · '+r.contract.name.toUpperCase());updateTaxiUI();return}if(Math.hypot(p.x-r.destination.x,p.y-r.destination.y)>44){showToast('FOLLOW THE GOLD PIN TO '+r.name.toUpperCase());return}const baseFare=taxiFare(),won=taxiContractMet(r,baseFare),cleanBonus=r.clean&&r.pedHits===0?8:0,contractBonus=won?r.contract.bonus:0,tip=cleanBonus+contractBonus,fare=baseFare+tip;state.money+=fare;state.taxiCompleted++;state.taxiStats.rides++;state.taxiStats.tips+=tip;state.taxiStats.bestFare=Math.max(state.taxiStats.bestFare,fare);state.taxiStats.streak=r.clean&&r.pedHits===0?state.taxiStats.streak+1:0;const stars=won&&r.clean?5:r.clean?4:r.pedHits?2:3;state.taxiStats.rating=Math.max(1,Math.min(5,(state.taxiStats.rating*(state.taxiStats.rides-1)+stars)/state.taxiStats.rides));state.taxiRide=null;spawnBurst(p.x,p.y,'#ffd36f',14);shakeScreen(.8,.15);play(pickupSound);showToast('FARE $'+baseFare+' · TIP $'+tip+(won?' · CONTRACT CLEAR':' · CONTRACT MISSED'));updateUI();save();setTimeout(()=>{if(state.started&&state.mode==='taxi')createTaxiRide(false)},900)}
window.addEventListener('pagehide',()=>{if(state.started)save()});
function friendPoint(id){const col=id%5,row=Math.floor(id/5),cx=col*(MAP/5)+(MAP/10),cy=row*(MAP/8)+(MAP/16);return{x:nearestRoadLane(cx+((id*53)%130)-65),y:nearestRoadLane(cy+((id*37)%90)-45)}}
function nextFriend(){if(!state.friendDeck?.length){state.friendDeck=Array.from({length:friendContacts.length},(_,i)=>i);for(let i=state.friendDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.friendDeck[i],state.friendDeck[j]]=[state.friendDeck[j],state.friendDeck[i]]}}return friendContacts[state.friendDeck.pop()]}
function friendMissionTarget(){const m=state.friendMission;if(!m)return null;return m.stage==='meet'||m.stage==='return'?m.meet:m.destination}
function startFriendCall(){const friend=nextFriend();state.friendCall={friend,timeLeft:17};friendCallerEl.textContent=friend.name.toUpperCase();friendMessageEl.textContent=friend.call;friendCallEl.classList.add('visible');showToast('PHONE · '+friend.name.toUpperCase()+' IS CALLING · E TO ANSWER')}
function answerFriendCall(){if(!state.friendCall)return;const friend=state.friendCall.friend;state.friendCall=null;friendCallEl.classList.remove('visible');state.friendHudSnapshot={mission:state.mission,count:missionCount.textContent,contact:contactEl.textContent,title:missionTitle.textContent,line:missionLine.textContent};const meet=friendPoint(friend.id),dest=friendPoint((friend.id+13+(friend.id%4)*5)%friendContacts.length);state.friendMission={friend,stage:'meet',meet,destination:dest,reward:friend.reward,timeLeft:70,late:false,packageTaken:false};showToast(friend.name.toUpperCase()+' · MEET ME AT THE F PIN');updateFriendHUD();updateGuidance()}
function ignoreFriendCall(){if(!state.friendCall)return;friendCallEl.classList.remove('visible');state.friendCall=null;state.friendMissed++;state.friendCallTimer=55+Math.random()*45;showToast('CALL DECLINED · THEY WILL TRY AGAIN LATER')}
function startFriendErrand(){const m=state.friendMission;if(!m)return;if(m.friend.kind==='retrieve'){m.stage='retrieve';showToast(m.friend.name.toUpperCase()+' · PICK UP '+m.friend.parcel.toUpperCase())}else if(m.friend.kind==='race'){m.stage='race';m.timeLeft=65+Math.random()*20;showToast('RACE ON · REACH THE GOLD PIN BEFORE TIME') }else{m.stage='deliver';showToast('PARCEL SECURED · DELIVER IT TO THE GOLD PIN')}updateFriendHUD();updateGuidance()}
function finishFriendErrand(){const m=state.friendMission;if(!m)return;let reward=m.reward;if(m.friend.kind==='race'&&m.late)reward=Math.ceil(reward*.55);state.money+=reward;state.friendCompleted++;spawnBurst(state.player.x,state.player.y,'#62e4d4',12);shakeScreen(.7,.14);showToast(m.friend.name.toUpperCase()+' · ERRAND CLEAR · +$'+reward);state.friendMission=null;state.friendCallTimer=70+Math.random()*65;if(state.friendHudSnapshot&&state.friendHudSnapshot.mission===state.mission){missionCount.textContent=state.friendHudSnapshot.count;contactEl.textContent=state.friendHudSnapshot.contact;missionTitle.textContent=state.friendHudSnapshot.title;missionLine.textContent=state.friendHudSnapshot.line}else if(state.mission<missions.length){const main=missions[state.mission];missionCount.textContent='JOB '+String(state.mission+1).padStart(2,'0')+' / 25';contactEl.textContent=main[1].toUpperCase();missionTitle.textContent=main[0];missionLine.textContent=main[2]}else{missionCount.textContent='CITY LEGEND';contactEl.textContent='BAYBELL LOVES YOU';missionTitle.textContent='The city is yours.';missionLine.textContent='Every bad idea paid off.'}state.friendHudSnapshot=null;updateUI();updateGuidance();save()}
function updateFriendCalls(dt){if(state.mode!=='story'||!state.started)return;if(state.friendCall){state.friendCall.timeLeft-=dt;if(state.friendCall.timeLeft<=0){const name=state.friendCall.friend.name;friendCallEl.classList.remove('visible');state.friendCall=null;state.friendMissed++;state.friendCallTimer=55+Math.random()*45;showToast('MISSED CALL · '+name+' WILL TRY AGAIN LATER')}return}if(state.friendMission||state.cityActivity)return;state.friendCallTimer-=dt;if(state.friendCallTimer<=0){startFriendCall();state.friendCallTimer=0}}
function updateFriendHUD(){updateFriendMission()}
function updateFriendMission(){const m=state.friendMission;if(!m)return;const area=mapAreas[mapAreaId(friendMissionTarget().x,friendMissionTarget().y)];missionCount.textContent='FRIEND MAP · '+String(m.friend.id+1).padStart(2,'0')+'/40';contactEl.textContent=m.friend.name.toUpperCase()+' · '+m.friend.parcel.toUpperCase();if(m.stage==='meet'){missionTitle.textContent='MEET '+m.friend.name.toUpperCase();missionLine.textContent='Go to the F pin in '+area.name+'. Press E beside your friend.'}else if(m.stage==='retrieve'){missionTitle.textContent='PICK UP THE PARCEL';missionLine.textContent='Find '+m.friend.parcel+' at '+area.name+'. Press E at the pin.'}else if(m.stage==='return'){missionTitle.textContent='RETURN TO '+m.friend.name.toUpperCase();missionLine.textContent='Bring '+m.friend.parcel+' back to the F pin. Press E.'}else if(m.stage==='race'){missionTitle.textContent='FRIENDLY RACE · '+Math.ceil(m.timeLeft)+'S';missionLine.textContent='Race to '+area.name+' and press E before the clock runs out.'}else{missionTitle.textContent='DELIVER FOR '+m.friend.name.toUpperCase();missionLine.textContent='Take '+m.friend.parcel+' to '+area.name+'. Press E at the pin.'}}
function getContextGuidance(){if(state.friendCall)return 'Phone ringing · press E or ANSWER, or IGNORE the call.';if(state.cityActivity){const a=state.cityActivity;if(a.type==='courier')return a.stage==='pickup'?'Go to the P pin; press E to pick up the parcel.':'Follow the gold road to D and press E to deliver.';if(a.type==='race')return a.stage==='start'?'Reach the S pin and press E to start the race.':'Race to the finish · '+Math.ceil(a.timeLeft)+' seconds left.';if(a.type==='cache')return 'Search the block on foot for three glowing tokens.';return 'Visit the marked landmark and press E nearby.'}if(state.friendMission){const m=state.friendMission;if(m.stage==='meet')return 'Meet '+m.friend.name+' at the F pin; press E when close.';if(m.stage==='retrieve')return 'Go to the gold pin and press E to collect '+m.friend.parcel+'.';if(m.stage==='return')return 'Return '+m.friend.parcel+' to '+m.friend.name+' at the F pin.';if(m.stage==='race')return 'Race to the gold destination · '+Math.ceil(m.timeLeft)+' seconds left.';return 'Deliver '+m.friend.parcel+' to the gold pin, then press E.'}if(state.mode==='taxi'&&state.taxiRide)return state.taxiRide.onboard?'Follow D to '+mapAreas[mapAreaId(state.taxiRide.destination.x,state.taxiRide.destination.y)].name+'; press E to drop off.':'Drive to P and press E to pick up '+state.taxiRide.name+'.';if(state.mode==='taxi')return 'Wait for a new fare request.';if(state.sideJob?.active)return state.sideJob.stage==='pickup'?'Optional side job · reach the gold $ pin and press E.':'Side-job package onboard · follow the gold delivery pin.';if(state.missionActive){const type=missions[state.mission][3];if(type==='car')return 'Find the marked car; walk close and press E to enter.';if(type==='drive')return state.player.inCar?'Drive to the story pin; the map shows the destination.':'Find a car, then follow the story pin.';if(type==='collect')return state.player.inCar?'Press E to leave the car, then collect every envelope.':'Walk over the glowing envelopes; the counter shows how many remain.';if(type==='escape')return 'Stay away from police until the heat cools; safehouses can help.';if(type==='wreck')return 'Get in a car and hit the rival vehicle until it gives up.'}return 'Explore Baybell · J opens 50 city jobs; H shows another tip.'}
function updateGuidance(){if(!guidanceTextEl)return;guidanceHudEl.classList.toggle('friend-guide',!!(state.friendMission||state.friendCall));const text=state.guidanceTimer>0&&state.guidanceIndex>=0?playerHints[state.guidanceIndex]:getContextGuidance();if(text!==state.guidanceLast){guidanceTextEl.textContent=text;state.guidanceLast=text}}
function cycleGuidance(){state.guidanceIndex=(state.guidanceIndex+1)%playerHints.length;state.guidanceTimer=8;state.guidanceLast='';updateGuidance();showToast('TIP '+String(state.guidanceIndex+1).padStart(2,'0')+' / '+playerHints.length)}
function friendInteract(){const m=state.friendMission;if(!m)return false;const target=friendMissionTarget();if(Math.hypot(state.player.x-target.x,state.player.y-target.y)>38)return false;if(m.stage==='meet'){startFriendErrand();return true}if(m.stage==='retrieve'){m.stage='return';m.packageTaken=true;spawnBurst(target.x,target.y,'#ffc86f',7);showToast('GOT IT · TAKE IT BACK TO '+m.friend.name.toUpperCase());updateFriendHUD();updateGuidance();return true}finishFriendErrand();return true}
function drawFriendContact(){const m=state.friendMission;if(!m||!(m.stage==='meet'||m.stage==='return'))return;const p=m.meet,x=Math.round(p.x-state.camera.x),y=Math.round(p.y-state.camera.y);if(x<-18||x>W+18||y<-20||y>H+16)return;ctx.save();ctx.translate(x,y+Math.sin(state.frame*3)*1.2);ctx.fillStyle='rgba(8,10,14,.6)';ctx.beginPath();ctx.ellipse(0,5,7,2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e3c18a';ctx.fillRect(-2,-9,5,5);ctx.fillStyle='#ff7895';ctx.fillRect(-4,-4,9,8);ctx.fillStyle='#e4d7be';ctx.fillRect(-5,-2,2,5);ctx.fillStyle='#62e4d4';ctx.fillRect(5,-5,2,6);ctx.fillStyle='#30343a';ctx.fillRect(-3,4,2,3);ctx.fillRect(2,4,2,3);ctx.font='5px monospace';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText(m.friend.name.toUpperCase(),0,-12);ctx.restore()}
function activityPoint(region,index,variant=0){const i=index%10;let x,y;if(region==='north'){x=160+((i*211+variant*367)%1680);y=145+((i*83+variant*131)%285)}else if(region==='south'){x=160+((i*197+variant*313)%1680);y=1650+((i*71+variant*149)%280)}else if(region==='east'){x=1650+((i*47+variant*71)%280);y=560+((i*191+variant*317)%900)}else if(region==='west'){x=145+((i*53+variant*89)%300);y=560+((i*181+variant*293)%900)}else{x=650+((i*113+variant*197)%750);y=650+((i*173+variant*281)%750)}return{x:mapRoadLane(x),y:mapRoadLane(y)}}
function cityActivityTarget(){const a=state.cityActivity;if(!a)return null;if(a.type==='courier')return a.stage==='pickup'?a.start:a.target;if(a.type==='race')return a.stage==='start'?a.start:a.target;if(a.type==='cache')return a.items.find(q=>!q.got)||a.target;return a.target}
