function openActivityBoard(){if(!state.started){showToast('START GAME MODE TO OPEN THE CITY BOARD');return}if(state.mode!=='story'){showToast('CITY BOARD IS AVAILABLE IN GAME MODE');return}if(state.paused)return;if(state.cityActivity)state.activityIndex=state.cityActivity.id;else{const first=cityActivities.find(q=>!state.activityDone.includes(q.id));if(first)state.activityIndex=first.id}state.boardOpen=true;state.paused=true;document.querySelector('.game-frame').classList.add('board-open');activityBoardEl.hidden=false;audio.pause();renderActivityBoard()}
