function startCityActivity(){if(state.cityActivity)return;if(state.friendCall||state.friendMission){showToast('FINISH YOUR FRIEND CALL FIRST');return}const activity=cityActivities[state.activityIndex];if(state.activityDone.includes(activity.id)){showToast('THAT CITY JOB IS ALREADY CLEAR');return}const region=activity.region,start=activityPoint(region,activity.id,0),target=activityPoint(region,activity.id,1);state.activityHudSnapshot={mission:state.mission,count:missionCount.textContent,contact:contactEl.textContent,title:missionTitle.textContent,line:missionLine.textContent};let job={activity,type:activity.type,id:activity.id,start,target,stage:activity.type==='courier'?'pickup':activity.type==='race'?'start':activity.type==='cache'?'search':'visit',timeLeft:0,late:false,items:[]};if(activity.type==='cache'){job.items=[{x:target.x-25,y:target.y-9,got:false},{x:target.x+24,y:target.y-5,got:false},{x:target.x+2,y:target.y+26,got:false}]}state.cityActivity=job;closeActivityBoard();showToast('CITY JOB · '+activity.title.toUpperCase());updateCityActivityHUD();updateGuidance();renderActivityBoard()}
function restoreActivityHud(){if(state.activityHudSnapshot&&state.activityHudSnapshot.mission===state.mission){missionCount.textContent=state.activityHudSnapshot.count;contactEl.textContent=state.activityHudSnapshot.contact;missionTitle.textContent=state.activityHudSnapshot.title;missionLine.textContent=state.activityHudSnapshot.line}else if(state.mission<missions.length){const m=missions[state.mission];missionCount.textContent='JOB '+String(state.mission+1).padStart(2,'0')+' / 25';contactEl.textContent=m[1].toUpperCase();missionTitle.textContent=m[0];missionLine.textContent=m[2]}else{missionCount.textContent='CITY LEGEND';contactEl.textContent='BAYBELL LOVES YOU';missionTitle.textContent='The city is yours.';missionLine.textContent='Every bad idea paid off.'}state.activityHudSnapshot=null}
function finishCityActivity(){const job=state.cityActivity;if(!job)return;let reward=job.activity.reward;if(job.type==='race'&&job.late)reward=Math.floor(reward*.6);state.money+=reward;if(!state.activityDone.includes(job.id))state.activityDone.push(job.id);state.cityActivity=null;spawnBurst(state.player.x,state.player.y,'#ffc86f',12);play(pickupSound);showToast('CITY JOB CLEAR · +$'+reward);restoreActivityHud();updateUI();updateGuidance();save()}
function updateCityActivityHUD(){const job=state.cityActivity;if(!job)return;const n=job.items.filter(q=>q.got).length;missionCount.textContent='CITY JOB · '+String(job.id+1).padStart(2,'0')+'/50';contactEl.textContent=job.activity.contact.toUpperCase()+' · '+job.activity.region.toUpperCase();if(job.type==='courier'){missionTitle.textContent=job.stage==='pickup'?'COLLECT · '+job.activity.title.toUpperCase():'DELIVER · '+job.activity.title.toUpperCase();missionLine.textContent=job.stage==='pickup'?'Reach the P pin and press E to collect the parcel.':'Take the parcel to D and press E to deliver.'}else if(job.type==='race'){missionTitle.textContent=job.stage==='start'?'START · '+job.activity.title.toUpperCase():'RACE · '+Math.ceil(job.timeLeft)+'S LEFT';missionLine.textContent=job.stage==='start'?'Reach the S pin and press E to start the clock.':'Reach the finish pin and press E before time runs out.'}else if(job.type==='cache'){missionTitle.textContent='SEARCH · '+job.activity.title.toUpperCase();missionLine.textContent='Collect the three tokens on foot · '+n+'/3 found.'}else{missionTitle.textContent='VISIT · '+job.activity.title.toUpperCase();missionLine.textContent='Find the marked landmark and press E when close.'}}
function updateCityActivity(dt,p){const job=state.cityActivity;if(!job)return;if(job.type==='race'&&job.stage==='race'){job.timeLeft=Math.max(0,job.timeLeft-dt);if(job.timeLeft===0&&!job.late){job.late=true;showToast('CLOCK EXPIRED · FINISH FOR A SMALLER REWARD')}}if(job.type==='cache'&&!p.inCar){for(const item of job.items){if(!item.got&&Math.hypot(item.x-p.x,item.y-p.y)<15){item.got=true;play(pickupSound);showToast('TOKEN FOUND · '+job.items.filter(q=>q.got).length+'/3')}}if(job.items.every(q=>q.got))finishCityActivity()}}
function cityActivityInteract(){const job=state.cityActivity;if(!job)return false;if(job.type==='cache')return false;const target=cityActivityTarget();if(!target||Math.hypot(state.player.x-target.x,state.player.y-target.y)>40)return false;if(job.type==='courier'){if(job.stage==='pickup'){job.stage='deliver';showToast('PARCEL SECURED · FOLLOW THE D PIN')}else finishCityActivity()}else if(job.type==='race'){if(job.stage==='start'){job.stage='race';job.timeLeft=72+(job.id%4)*8;showToast('RACE ON · '+Math.ceil(job.timeLeft)+' SECONDS')}else finishCityActivity()}else finishCityActivity();updateCityActivityHUD();updateGuidance();return true}
