function updateUI(){cashEl.textContent='$'+String(state.money).padStart(4,'0');starsEl.innerHTML=Array.from({length:5},(_,i)=>'<span class="'+(i<state.wanted?'lit':'')+'">'+(i<state.wanted?'★':'☆')+'</span>').join('');if(state.mode==='taxi')updateTaxiUI()}
