 if(p.inCar){p.inCar=false;if(p.car){p.car.occupied=false;p.car.currentSpeed=0;p.x+=Math.cos(p.car.angle+Math.PI/2)*17;p.y+=Math.sin(p.car.angle+Math.PI/2)*17;}p.speed=0;showToast('BACK ON FOOT');return}
 let near=state.cars.filter(c=>!c.police&&!c.occupied&&c.health>0&&!c.disabled&&Math.hypot(c.x-p.x,c.y-p.y)<24).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];
 if(near){p.inCar=true;p.car=near;near.occupied=true;near.traffic=false;near.currentSpeed=0;p.x=near.x;p.y=near.y;p.dir=near.angle;state.wanted=Math.min(5,state.wanted+1);state.heatQuiet=0;showToast('HOT WHEELS · HEAT +1');updateUI();return}
