drawPigeon();drawRegionalWeather();drawAtmosphere();drawMinimap();ctx.fillStyle='#11131be5';ctx.fillRect(0,0,256,13);ctx.fillStyle='#c9c7c0';ctx.font='6px monospace';ctx.textAlign='left';const activeRegion=worldRegionId(state.player.x,state.player.y);ctx.fillText((activeRegion>=0?worldRegions[activeRegion].name:districts[districtId(state.player.x,state.player.y)].name)+'  •  '+String(state.frame|0).padStart(5,'0'),6,9);ctx.textAlign='right';ctx.fillStyle=state.wanted?'#ff7087':'#78d9ce';ctx.fillText(state.safehouse?'SAFEHOUSE':state.player.inCar?(state.player.car?.health<=0?'CAR DEAD':'CAR '+(state.player.car?.health??3)+'/3'):'ROOK ON FOOT',202,9);
